from pathlib import Path
import re
p=Path('miseno_docentes.html');s=p.read_text(encoding='utf-8')
a=s.index('function projects(){');b=s.index('\nfunction render(',a)
s=s[:a]+s[b:]
extra=Path('tmp/miseno_projects.js').read_text(encoding='utf-8')
extra=extra.replace("toast('Enregistré'.replace('Enregistré','Enregistrado'.replace('Enregistrado','Guardado'))+' en el proyecto y vinculado a los alumnos.')", "toast('Guardado en el proyecto y vinculado a los alumnos.')")
s=s.replace('\nrender();\nsetTimeout','\n'+extra+'\nrender();\nsetTimeout')
css='''
.project-brief{display:grid;grid-template-columns:minmax(0,1fr) 280px;gap:24px;margin-bottom:20px}.project-brief p{margin-top:10px}.project-tabs button[aria-pressed=true]{border-bottom-color:var(--blue);color:#294fae;font-weight:700}.project-columns{display:grid;grid-template-columns:290px minmax(0,1fr);gap:24px;align-items:start}.project-roster{display:grid;gap:10px;margin-top:20px}.team-select{display:flex;flex-direction:column;gap:6px;padding:15px;text-align:left;border:1px solid #d5dfe1;background:#ffffff66;border-radius:12px;transition:background .2s,border-color .2s}.team-select[aria-pressed=true]{border-color:#315dce;background:#e8eef9bb}.team-select strong{font-family:var(--display);font-size:20px;font-weight:400}.project-member-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:20px}.project-checkpoints{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin-top:24px;padding-bottom:20px;border-bottom:1px solid var(--line)}.project-checkpoints p{margin-top:8px}.incident-list{display:grid;gap:20px;margin-top:24px}.incident-card{padding:22px;border:1px solid #ddded4;background:#fff9;border-radius:14px}.incident-card>.small{margin-top:10px}.member-picker{display:grid;grid-template-columns:1fr 1fr;gap:10px;max-height:270px;overflow:auto;padding:8px;border:1px solid var(--line);border-radius:12px;background:#fff8}.member-picker .check{margin:0;padding:9px;font-size:14px}.member-picker small{display:block;font-size:12px}#team-name,#incident-title{width:100%}#project-panel{min-height:350px}.incident-card .timeline:empty{display:none}.project-member-cards .student p{margin-bottom:0}@media(max-width:1000px){.project-columns{grid-template-columns:240px minmax(0,1fr)}.project-brief{grid-template-columns:1fr}.project-checkpoints{grid-template-columns:1fr}}@media(max-width:760px){.project-columns{grid-template-columns:1fr}.project-roster{grid-template-columns:repeat(2,minmax(0,1fr))}.project-member-cards{grid-template-columns:repeat(2,minmax(0,1fr))}.project-tabs{gap:3px}.project-tabs button{padding:12px}.incident-card{padding:16px}}@media(max-width:480px){.member-picker,.project-member-cards,.project-roster{grid-template-columns:1fr}.project-tabs button{font-size:14px}.incident-card>.row{flex-direction:column}.project-columns>.card>.row{flex-wrap:wrap}}
'''
s=s.replace('</style>',css+'\n</style>')
p.write_text(s,encoding='utf-8');Path('tmp/miseno_check.js').write_text(re.search(r'<script>(.*?)</script>',s,re.S).group(1),encoding='utf-8')
print('Proyectos integrado')
